from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding='utf-8')
    if old not in text:
        raise RuntimeError(f'Expected block not found in {path}')
    path.write_text(text.replace(old, new, 1), encoding='utf-8')

native = ROOT / 'Services' / 'NativeIec61850Client.cs'
replace_once(
    native,
    '''    private static void ApplyDiscoveryReadValue(SignalDefinition signal, object value)\n    {\n        if (value is Iec61850ReadValue rich)\n        {\n            signal.Value = Iec61850ValueFormatter.Format(rich.Value ?? rich.ToString(), signal.DataType, signal.Unit);\n            signal.Quality = rich.HasQuality ? rich.Quality : "Good";\n            signal.DeviceTimestamp = rich.HasDeviceTimestamp ? rich.DeviceTimestamp : "-";\n        }\n        else\n        {\n            signal.Value = Iec61850ValueFormatter.Format(value, signal.DataType, signal.Unit);\n            signal.Quality = "Good";\n        }\n        signal.ProbeStatus = "Readable";\n        signal.Timestamp = DateTime.Now;\n    }\n''',
    '''    private static void ApplyDiscoveryReadValue(SignalDefinition signal, object value)\n    {\n        var receivedAtUtc = value is Iec61850ReadValue rich\n            ? rich.ReceivedAtUtc\n            : DateTimeOffset.UtcNow;\n        var envelope = Iec61850ProductionTelemetryNormalizer.FromReadObject(\n            value,\n            signal.DataType,\n            signal.Unit,\n            receivedAtUtc,\n            signal.ObjectReference,\n            value is Iec61850ReadValue read ? read.ReadReference : signal.ObjectReference);\n\n        signal.Value = envelope.HasProcessValue\n            ? Iec61850ValueFormatter.Format(envelope.Value ?? envelope.DisplayValue, signal.DataType, signal.Unit)\n            : "-";\n        signal.Quality = envelope.QualityText;\n        signal.DeviceTimestamp = Iec61850ProductionTelemetryNormalizer.SourceTimestampTextOrUnknown(\n            envelope,\n            value is Iec61850ReadValue sourceRead ? sourceRead.DeviceTimestamp : null);\n        signal.ProbeStatus = envelope.HasProcessValue ? "Readable" : "Readable / no process value";\n        signal.Timestamp = DateTime.Now;\n    }\n''')

monitor = ROOT / 'Services' / 'Iec61850MonitorRuntime.cs'
replace_once(
    monitor,
    '''                var reportQuality = update.HasQuality && IsUsefulProcessField(update.Quality)\n                    ? NormalizeQuality(update.Quality)\n                    : state.HasValue ? state.Quality : "Pending / q not supplied";\n                var reportTimestamp = update.HasTimestamp && IsUsefulProcessField(update.Timestamp)\n                    ? update.Timestamp\n                    : state.HasValue ? state.DeviceTimestamp : "-";\n\n                ApplyValueUpdate(\n                    session,\n                    point,\n                    display,\n                    reportQuality,\n                    reportTimestamp,\n''',
    '''                var reportEnvelope = Iec61850ProductionTelemetryNormalizer.FromComponents(\n                    update.HasValue ? update.Value : null,\n                    update.HasValue ? display : "-",\n                    update.HasQuality && IsUsefulProcessField(update.Quality) ? update.Quality : null,\n                    update.HasTimestamp && IsUsefulProcessField(update.Timestamp) ? update.Timestamp : null,\n                    new DateTimeOffset(DateTime.SpecifyKind(receivedUtc, DateTimeKind.Utc)),\n                    update.Reference);\n                var reportQuality = reportEnvelope.QualityText;\n                var reportTimestamp = Iec61850ProductionTelemetryNormalizer.SourceTimestampTextOrUnknown(\n                    reportEnvelope,\n                    update.Timestamp);\n\n                ApplyValueUpdate(\n                    session,\n                    point,\n                    display,\n                    reportQuality,\n                    reportTimestamp,\n''')
replace_once(
    monitor,
    '''                    trustReportEdge: true,\n                    hasProcessValue: update.HasValue);''',
    '''                    trustReportEdge: true,\n                    hasProcessValue: reportEnvelope.HasProcessValue);''')
replace_once(
    monitor,
    '''                var rich = resolved.Value as Iec61850ReadValue;\n                var raw = Iec61850ReadValue.Unwrap(resolved.Value);\n                var display = Iec61850ValueFormatter.Format(raw, point.IecDataType, point.Unit);\n                var quality = rich?.HasQuality == true ? rich.Quality : state.Quality;\n                var deviceTimestamp = rich?.HasDeviceTimestamp == true ? rich.DeviceTimestamp : state.DeviceTimestamp;\n\n                if ((rich?.HasQuality != true || rich?.HasDeviceTimestamp != true) &&\n                    nowUtc >= session.RecoveryWarmupUntilUtc &&\n                    nowUtc >= state.NextCompanionPollUtc)\n                {\n                    state.NextCompanionPollUtc = nowUtc.AddMilliseconds(GetCompanionPollIntervalMs(point));\n                    var companions = await ReadCompanionAttributesAsync(\n                        session.Client,\n                        point,\n                        resolved.EffectiveReference,\n                        quality,\n                        deviceTimestamp,\n                        cancellationToken).ConfigureAwait(false);\n                    quality = companions.Quality;\n                    deviceTimestamp = companions.DeviceTimestamp;\n                }\n\n                var normalizedQuality = NormalizeQuality(quality);\n                var normalizedTimestamp = string.IsNullOrWhiteSpace(deviceTimestamp) ? "-" : deviceTimestamp;\n''',
    '''                var rich = resolved.Value as Iec61850ReadValue;\n                var raw = Iec61850ReadValue.Unwrap(resolved.Value);\n                var display = Iec61850ValueFormatter.Format(raw, point.IecDataType, point.Unit);\n                // Never carry forward stale Good/q or relay time when the current network read\n                // did not actually supply them. Companion reads may enrich this sample, but if\n                // they fail the defensive envelope below keeps quality Unknown and source time '-'.\n                var quality = rich?.HasQuality == true ? rich.Quality : string.Empty;\n                var deviceTimestamp = rich?.HasDeviceTimestamp == true ? rich.DeviceTimestamp : string.Empty;\n\n                if ((rich?.HasQuality != true || rich?.HasDeviceTimestamp != true) &&\n                    nowUtc >= session.RecoveryWarmupUntilUtc &&\n                    nowUtc >= state.NextCompanionPollUtc)\n                {\n                    state.NextCompanionPollUtc = nowUtc.AddMilliseconds(GetCompanionPollIntervalMs(point));\n                    var companions = await ReadCompanionAttributesAsync(\n                        session.Client,\n                        point,\n                        resolved.EffectiveReference,\n                        quality,\n                        deviceTimestamp,\n                        cancellationToken).ConfigureAwait(false);\n                    quality = companions.Quality;\n                    deviceTimestamp = companions.DeviceTimestamp;\n                }\n\n                var receivedAtUtc = rich?.ReceivedAtUtc ?? DateTimeOffset.UtcNow;\n                var envelope = Iec61850ProductionTelemetryNormalizer.FromComponents(\n                    raw,\n                    display,\n                    quality,\n                    deviceTimestamp,\n                    receivedAtUtc,\n                    point.IecReference,\n                    resolved.EffectiveReference);\n                var normalizedQuality = envelope.QualityText;\n                var normalizedTimestamp = Iec61850ProductionTelemetryNormalizer.SourceTimestampTextOrUnknown(\n                    envelope,\n                    deviceTimestamp);\n''')
replace_once(
    monitor,
    '''                    DateTime.UtcNow,\n                    status,\n                    trustReportEdge: false);''',
    '''                    DateTime.UtcNow,\n                    status,\n                    trustReportEdge: false,\n                    hasProcessValue: envelope.HasProcessValue);''')

normalizer = ROOT / 'Services' / 'Iec61850ProductionTelemetryNormalizer.cs'
normalizer.write_text('''namespace ArIED61850Tester.Services;\n\n/// <summary>\n/// Single production boundary between decoded IEC 61850 network data and UI/runtime state.\n/// It preserves a valid source timestamp, never fabricates PC time as relay evidence, and\n/// never promotes missing/unknown quality to Good.\n/// </summary>\npublic static class Iec61850ProductionTelemetryNormalizer\n{\n    public static Iec61850TelemetryEnvelope FromReadObject(\n        object? value,\n        string dataType,\n        string unit,\n        DateTimeOffset? receivedAtUtc = null,\n        string? sourceReference = null,\n        string? readReference = null)\n    {\n        if (value is Iec61850ReadValue rich)\n            return Iec61850TelemetryEnvelope.FromReadValue(rich, receivedAtUtc);\n\n        var display = Iec61850ValueFormatter.Format(value, dataType, unit);\n        return FromComponents(\n            value,\n            display,\n            quality: null,\n            deviceTimestamp: null,\n            receivedAtUtc ?? DateTimeOffset.UtcNow,\n            sourceReference,\n            readReference);\n    }\n\n    public static Iec61850TelemetryEnvelope FromComponents(\n        object? value,\n        string? displayValue,\n        string? quality,\n        string? deviceTimestamp,\n        DateTimeOffset receivedAtUtc,\n        string? sourceReference = null,\n        string? readReference = null)\n        => Iec61850TelemetryEnvelope.FromReadValue(new Iec61850ReadValue\n        {\n            Value = value,\n            DisplayValue = displayValue?.Trim() ?? string.Empty,\n            Quality = quality?.Trim() ?? string.Empty,\n            DeviceTimestamp = deviceTimestamp?.Trim() ?? string.Empty,\n            SourceReference = sourceReference?.Trim() ?? string.Empty,\n            ReadReference = readReference?.Trim() ?? string.Empty,\n            ReceivedAtUtc = receivedAtUtc\n        }, receivedAtUtc);\n\n    public static string SourceTimestampTextOrUnknown(\n        Iec61850TelemetryEnvelope envelope,\n        string? originalTimestamp)\n        => envelope.SourceTimestampUtc.HasValue\n            ? originalTimestamp?.Trim() ?? "-"\n            : "-";\n}\n''', encoding='utf-8')

test = ROOT / 'tests' / 'ARSAS.Tests' / 'P8ProductionTelemetryIntegrationTests.cs'
test.write_text('''using System.Reflection;\nusing ArIED61850Tester.Models;\nusing ArIED61850Tester.Services;\n\nnamespace ARSAS.Tests;\n\npublic sealed class P8ProductionTelemetryIntegrationTests\n{\n    [Fact]\n    public void ProductionNormalizer_MissingQualityIsNotGood_AndMalformedTimestampStaysUnknown()\n    {\n        var envelope = Iec61850ProductionTelemetryNormalizer.FromComponents(\n            value: true,\n            displayValue: "True",\n            quality: null,\n            deviceTimestamp: "10:00:31",\n            receivedAtUtc: new DateTimeOffset(2026, 9, 11, 3, 0, 0, TimeSpan.Zero),\n            sourceReference: "LD0/LLN0.Mod.stVal");\n\n        Assert.Equal(Iec61850TelemetryQualityState.Questionable, envelope.QualityState);\n        Assert.Equal("Unknown", envelope.QualityText);\n        Assert.NotEqual(Iec61850TelemetryQualityState.Good, envelope.QualityState);\n        Assert.Null(envelope.SourceTimestampUtc);\n        Assert.Equal("-", Iec61850ProductionTelemetryNormalizer.SourceTimestampTextOrUnknown(envelope, "10:00:31"));\n    }\n\n    [Fact]\n    public void ProductionNormalizer_ExplicitGoodAndCompleteRelayTimestampPassThrough()\n    {\n        const string relayTimestamp = "2026-09-11T03:04:05.125Z";\n        var envelope = Iec61850ProductionTelemetryNormalizer.FromComponents(\n            value: 1,\n            displayValue: "1",\n            quality: "Good",\n            deviceTimestamp: relayTimestamp,\n            receivedAtUtc: new DateTimeOffset(2026, 9, 11, 3, 4, 6, TimeSpan.Zero),\n            sourceReference: "LD0/LLN0.Mod.stVal");\n\n        Assert.True(envelope.IsValid);\n        Assert.Equal(Iec61850TelemetryQualityState.Good, envelope.QualityState);\n        Assert.Equal("Good", envelope.QualityText);\n        Assert.Equal(new DateTimeOffset(2026, 9, 11, 3, 4, 5, 125, TimeSpan.Zero), envelope.SourceTimestampUtc);\n        Assert.Equal(relayTimestamp, Iec61850ProductionTelemetryNormalizer.SourceTimestampTextOrUnknown(envelope, relayTimestamp));\n    }\n\n    [Fact]\n    public void DiscoveryProductionPath_DoesNotPromoteMissingQualityToGood()\n    {\n        var signal = new SignalDefinition\n        {\n            Name = "Mod",\n            ObjectReference = "LD0/LLN0.Mod.stVal",\n            DataType = "BOOLEAN"\n        };\n        var read = new Iec61850ReadValue\n        {\n            Value = true,\n            DisplayValue = "True",\n            Quality = string.Empty,\n            DeviceTimestamp = "10:00:31",\n            SourceReference = signal.ObjectReference,\n            ReceivedAtUtc = new DateTimeOffset(2026, 9, 11, 3, 0, 0, TimeSpan.Zero)\n        };\n\n        var method = typeof(NativeIec61850Client).GetMethod(\n            "ApplyDiscoveryReadValue",\n            BindingFlags.NonPublic | BindingFlags.Static);\n\n        Assert.NotNull(method);\n        method!.Invoke(null, [signal, read]);\n\n        Assert.Equal("Unknown", signal.Quality);\n        Assert.False(signal.Quality.Equals("Good", StringComparison.OrdinalIgnoreCase));\n        Assert.Equal("-", signal.DeviceTimestamp);\n        Assert.Equal("True", signal.Value);\n    }\n\n    [Fact]\n    public void RuntimeSource_UsesProductionEnvelopeBeforeStateSnapshotAndSoe()\n    {\n        var source = ReadRepoFile("Services/Iec61850MonitorRuntime.cs");\n\n        Assert.Contains("Iec61850ProductionTelemetryNormalizer.FromComponents", source, StringComparison.Ordinal);\n        Assert.Contains("hasProcessValue: envelope.HasProcessValue", source, StringComparison.Ordinal);\n        Assert.Contains("hasProcessValue: reportEnvelope.HasProcessValue", source, StringComparison.Ordinal);\n        Assert.DoesNotContain("var quality = rich?.HasQuality == true ? rich.Quality : state.Quality;", source, StringComparison.Ordinal);\n        Assert.DoesNotContain("var deviceTimestamp = rich?.HasDeviceTimestamp == true ? rich.DeviceTimestamp : state.DeviceTimestamp;", source, StringComparison.Ordinal);\n    }\n\n    private static string ReadRepoFile(string relativePath)\n    {\n        DirectoryInfo? directory = new(AppContext.BaseDirectory);\n        while (directory != null)\n        {\n            var candidate = Path.Combine(directory.FullName, relativePath);\n            if (File.Exists(candidate))\n                return File.ReadAllText(candidate).Replace("\\r\\n", "\\n", StringComparison.Ordinal);\n            directory = directory.Parent;\n        }\n\n        throw new FileNotFoundException(relativePath);\n    }\n}\n''', encoding='utf-8')

doc = ROOT / 'docs' / 'P8_RUNTIME_PERFORMANCE_RESILIENCE.md'
doc_text = doc.read_text(encoding='utf-8')
doc_needle = '''Relay timestamp parsing is deliberately strict. ARSAS accepts only complete ARIEC/ISO date-time shapes containing year, month, day, hour, minute, and second. Partial strings such as `10:00:31` are rejected because general date parsers can silently fill the missing date from the local PC. A zone-less decoded IEC `UtcTime` is interpreted as UTC by protocol semantics; explicit offsets are normalized to UTC. A malformed or incomplete source timestamp remains `null` and is never replaced by `ReceivedAtUtc` or local PC time.\n'''
doc_extra = '''\n`Iec61850ProductionTelemetryNormalizer` is wired into the actual production discovery, cyclic MMS validation, and final report-to-runtime projection paths. Normalization therefore occurs before `RuntimePointState`, point snapshots, and SOE metadata are updated. Missing q/t metadata is not inherited from an older sample as if it belonged to the current read; a failed companion read leaves quality `Unknown` and source time `-` rather than carrying forward stale `Good` or stale relay time.\n'''
if doc_needle not in doc_text:
    raise RuntimeError('P8 documentation anchor not found')
doc.write_text(doc_text.replace(doc_needle, doc_needle + doc_extra, 1), encoding='utf-8')

print('P8 production telemetry fix applied successfully.')
